S=Path(__file__).resolve().parents[1];e=runpy.run_path(str(S/'work/write_superdaily_early.py'));add=e['add'];out=e['out'];cost=e['cost']
idxnote='分鐘現貨須與期貨時間戳完全相等，缺根不以前值補；09:00分鐘現貨一律略過，交易仍是期貨一腿。'
add('HDSMA','以同步現貨分鐘價差帶反向做一口期貨，回中線或反向外帶退出；名稱中的MA及夜盤欄位並未實作。','價差與配對',['通過KBAR相位且有同時間現貨open，期貨open>現貨+空距離則目標−1，<現貨−多距離則+1；方向限制將不允許訊號轉0。','中線出場模式在帶內多單跨到>=現貨、空單跨到<=現貨才平；其餘同側帶內保留。反向外帶可一筆兩口翻倉。'],['每日DD模式在曆日切換以前根close零滑價平開；一般退出與最後根強平按open。','合約切換按close平倉、重設合約期累積損益基準，之後月損達限制則退場並等下一換約才放行。'],[cost,idxnote,'月損檢查在KBAR相位之前，價差訊號在其後；月損用浮盈加自換約以來累計實現，不是每月1日自動歸零。'],['進場時間、夜盤留倉模式、紅黑門檻及均線天數都只有設定／UI，核心完全未讀；沒有因此在次日開盤或依MA過濾進場。','月損距離只有遇換約才換算，私有值Clear未重設；首段或重用物件未必有按目前參數初始化月損。','每日DD平開只改統計切分，不是額外市場訊號；未使用共用最後交易截止限制入場。'],{'計算DD方式':'每日計算在曆日變更時，以前次通過KBAR取樣的close零滑價平開，不必是緊鄰前根或日收盤；若新日根未通過KBAR，last_qe未更新，可重複沿同一舊時間戳日換。交易時計算不插日換。','KBAR間隔ex':'價差策略依開始交易時間起分鐘相位執行；月停損與末端強平另可在不合相位時觸發。','開始交易時間':'KBAR相位起點，沒有額外開始前禁止進場條件。','進場方向':'只多／只空／雙向，外帶不允許方向會變成0而可平掉原反向倉。','多進場比':'同步現貨open減%或點數為下帶，期貨嚴格低於才多。','空進場比':'同步現貨open加%或點數為上帶，期貨嚴格高於才空。','中線原則':'遇中線出場：多跨回現貨以上或空跨回以下才平；不出場：帶內繼續保留。','進場時間':'此版核心未讀取，列出的次開／當收／夜開選項不改實際分鐘訊號。','當月最大損失':'按下一合約首open換算%或點數，浮盈加合約期實現<=負門檻則封鎖到下次換約；0不檢查。','作多夜盤處理':'僅影響參數顯示，核心未讀，沒有實際夜盤留平規則。','作多紅黑X':'核心未使用此多單紅黑門檻。','作多X日均線':'核心未計算或使用此均線。','作空夜盤處理':'僅UI參數，實際交易未使用。','作空紅黑X':'核心未使用此空單紅黑門檻。','作空X日均線':'核心未計算或使用此空單均線。'})
add('HDV','指定收盤時刻按期現日價差決定一口方向，再以每日開盤風控及VIX價差過大限制交易。','價差與波動濾網',['第一筆HHmm>=收盤進場時間且之前曾低於該時間，取現貨日收盤作上下帶：期貨open<=下帶多一口，>=上帶空一口。可直接反手，帶內保留。','換方向時把dayopen設0，等下個TradeDate變更才建立新開盤基準；不是從入場價計開盤停損。'],['每個TradeDate變更，以當日第一根open重設基準。通過KBAR時持多跌到基準−距離或持空漲到基準+距離就平。','日界取嚴格早於當日日曆日期的最近VIX資料，近月open−現貨欄或近月open−次月欄的絕對值>=門檻，先平既有並封鎖至下次日界重新判。','合約切換close平倉並重設合約期月損門檻；月損達負值且KBAR通過就停止本約後續。資料末筆open強平。'],[cost,'日界可插前根close零滑價日換；收盤方向用日現貨資料，雖載分鐘現貨但此核心沒有使用同步分鐘價差。','VIX訊號用資料欄位的近月open及現貨／次月參考，不是直接讀當根台指交易時刻的VIX即時成交。'],['進場方向欄位未被核心讀取，設只多仍會因上帶訊號放空。','第一日未遇TradeDate切換前dayopen為0，且每次新方向入場又清成0，該段沒有開盤停損。','月損第一段使用核心常數初值而非先換算設定，直到首個換倉事件才啟用所設參數；0也未作略過而可能零損益即封鎖。','GetIndexPrice可退回最近較早日；日界缺VIX資料回0，通常不封鎖，但門檻為0仍會成立。'],{'進場方向':'本版只有欄位與建構設定，核心不讀，不會限制單向。','多價差比':'以現貨日收盤減%或點數為逆價差多門檻，含等號。','空價差比':'以現貨日收盤加%或點數為正價差空門檻，含等號。','收盤進場時間':'HHmm第一筆>=時執行當日一次，須後續有小於該時刻報價才重設可進；非精確相等。','開盤停損比':'每TradeDate首open的%或點數，不是原始入場價；新方向進場後dayopen清0直到下一日界。','當月最大損失':'首段先用核心初值，換約後用下一open換%或點數；KBAR通過且合約期損益<=負值就封鎖，0未特判。','VIX價差檢查':'無略過；與現貨取aux1，與次月取aux2，與近月open作差，再以絕對值檢查。','VIX價差':'絕對價差>=此點數就日界退出並停止當日處理；不是按百分比。','KBAR間隔ex':'篩開盤停損與月停損；指定收盤建倉、VIX日界退出及末根平不需合相位。','開始交易時間':'上述ValidKBAR分鐘相位原點，不額外限制收盤建倉時間。','計算DD方式':'每日計算在TradeDate變更時於前根close零滑價平開，其他模式不插此日換。'})
for name,my in [('HDZ',False),('HDZmy',True)]:
 nn={'進場方向':'雙向／只多／只空，算完目標後限制成允許符號；可將不允許的留倉動作變成平倉。','多價差比':'同步現貨open減距離為逆價差門檻，%或點數，含等號。','空價差比':'同步現貨open加距離為正價差門檻，含等號。','多突破比':'每日參考open加%或點數，逆價差且期貨>=此線才多。','空突破比':'每日參考open減%或點數，正價差且期貨<=此線才空。','多停損比':'每日參考open減距離，已有多且存在同步指數時<=退出，不是以入場價計。','空停損比':'每日參考open加距離，已有空且存在同步指數時>=退出。','多留倉比':'每日參考open加此距離，收盤留倉時需價格>=此線且最近價差狀態為逆；可從空倉或空手轉多。','當月最大損失':'僅換倉後按下一open換距離，合約期浮盈+實現<=負門檻時封鎖至下次換約；0不啟用。','收盤進場時間':('缺同步現貨且HHmm精確等於時，用當根close當留／平價格；缺該分鐘不補。' if my else '缺同步現貨且本根<=時刻、下根跨過或時刻回退，才以本根open留／平；不是必須精確該分鐘。'),'留倉停損比':'決定留多當刻價格減距離成留倉損線，僅缺同步現貨且HHmm>收盤進場時間時open嚴格低於才平。','計算DD方式':('每日計算在曆日變更前根close零滑價平開。' if my else '每日計算在商品TradeDate變更前根close零滑價平開。')}
 add(name,'同步期現價差加開盤突破才入場，日盤按開盤線停損，收盤可依逆價差條件轉多留倉。','價差與突破',['有同步現貨分鐘且非09:00時更新正／逆價差狀態。空手需逆價差+向上突破才多，正價差+向下突破才空；已持倉時先只檢查每日開盤停損線。','每日突破、停損及多留倉線取'+('首筆及每次HHmm=08:45的open重設，缺08:45不按日期補重設。' if my else 'TradeDate首筆open重設，跨午夜按商品交易日判。')],['沒有同分鐘現貨時，收盤條件成立：最近價差逆且價格達多留倉線，目標+1；否則目標0。這可新進多或把空反成多，不只是保留既有多單。','留多後只有缺現貨且HHmm>收盤進場時間才檢查留倉線；跨午夜時刻變小會暫不檢查。同步現貨存在時走日盤開盤損分支。','合約事件設換倉旗標，此後平倉並略過到下一開盤重設；合約期月損可封鎖入場。資料末筆按open全部平。'],[cost,idxnote,'HDZmy與HDZ核心多數相同，差異為日界、開盤重設及收盤成交：'+('本版日DD用曆日，開盤只認08:45，缺現貨的精確收盤根複製open=close後交易。' if my else '本版日DD與開盤都用TradeDate，收盤採跨過時刻的前根open。')],['缺指數會保留最近價差狀態，收盤因此可能使用舊訊號；日盤停損也只在同步現貨存在時檢查，不能假設每根連續風控。','月損門檻私有值只在換約時換算，Clear未清，首段或重用物件可能沿先前狀態。','收盤留多分支只在沒有同步現貨的路徑執行，有該分鐘現貨反而不走留倉判斷。'],nn)
